(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
let W,H,scale=1,phase='build',selected='wood',drag=null,birds=3,score=0,shake=0,won=false;
const blocks=[],particles=[],clouds=[];
const rand=(a,b)=>a+Math.random*(b-a);
function resize(){const dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);makeClouds()}addEventListener('resize',resize);
function makeClouds(){clouds.length=0;for(let i=0;i<7;i++)clouds.push({x:rand(20,W),y:rand(70,H*.42),s:rand(.7,1.5)})}resize();
function groundY(){return H*.82}
function world(){return groundY()}
const birdsList=[];
function slingshot(){return{x:Math.max(85,W*.13),y:groundY()-45}}
function box(w,h,type='wood',x=0,y=0){return{x,y,w,h,type,vx:0,vy:0,a:0,va:0,sleep:false,hp:type==='stone'?5:type==='glass'?2:type==='bomb'?2:3}}
function resetBuild(){blocks.length=0;birdsList.length=0;particles.length=0;birds=3;score=0;won=false;phase='build';document.getElementById('buildTray').style.display='flex';document.getElementById('actions').style.display='flex';document.getElementById('phaseBadge').textContent='BUILD PHASE';document.getElementById('gameOver').style.display='none'}
resetBuild();
document.querySelectorAll('.blockChoice[data-type]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.blockChoice').forEach(q=>q.classList.remove('selected'));b.classList.add('selected');selected=b.dataset.type});
document.getElementById('deleteBtn').onclick=()=>{document.querySelectorAll('.blockChoice').forEach(q=>q.classList.remove('selected'));selected='erase';document.getElementById('deleteBtn').classList.add('selected')};
document.getElementById('resetBtn').onclick=()=>resetBuild();document.getElementById('againBtn').onclick=()=>resetBuild();
document.getElementById('doneBtn').onclick=startAttack;
function startAttack(){if(phase==='build'){phase='aim';document.getElementById('buildTray').style.display='none';document.getElementById('phaseBadge').textContent='ATTACK PHASE';spawnBird()} }
function spawnBird(){if(!birds)return;const s=slingshot();birdsList.push({x:s.x,y:s.y,r:16,vx:0,vy:0,active:false,shot:false,trail:[],alive:true});birds--}
function pos(e){const r=canvas.getBoundingRect();const t=e.touches?e.touches[0]:e;return{x:t.clientX-r.left,y:t.clientY-r.top}}
canvas.addEventListener('pointerdown',e=>{e.prevent.capture;const p=pos(e);if(phase==='build'){if(p.x<W*.62&&p.y<groundY()){let hit=null,idx=-1;for(let i=blocks.length-1;i>=0;i--){const b=blocks[i];if(p.x>b.x-b.w/2&&p.x<b.x+b.w/2&&p.y>b.y-b.h/2&&p.y<b.y+b.h/2){hit=b;idx=i;break}}if(selected==='erase'){if(idx>=0)blocks.splice(idx,1);return}if(!hit){let w=selected==='bomb'?42:38,h=selected==='bomb'?42:70;if(selected==='stone'||selected==='wood'||selected==='glass'){h=p.shiftKey?38:38;if(!p.shiftKey){/* no fixed */}}const b=box(w,h,selected,p.x,p.y);blocks.push(b);}}else if(phase==='aim'){const b=birdsList.find(q=>!q.shot&&q.alive);if(b&&Math.hypot(p.x-b.x,p.y-b.y)<55){drag=b;canvas.setPointerCapture(e.pointerId)}}});
canvas.addEventListener('pointermove',e=>{if(!drag)return;const p=pos(e),s=slingshot();let dx=p.x-s.x,dy=p.y-s.y,L=Math.hypot(dx,dy);if(L>110){dx*=110/L;dy*=110/L}drag.x=s.x+dx;drag.y=s.y+dy});
canvas.addEventListener('pointerup',e=>{if(drag){const s=slingshot(),dx=s.x-drag.x,dy=s.y-drag.y;if(Math.hypot(dx,dy)>12){drag.vx=dx*7;drag.vy=dy*7;drag.shot=true;drag.active=true}drag=null}});
function explode(x,y,power=1){shake=7;for(let i=blocks.length-1;i>=0;i--){const b=blocks[i],d=Math.hypot(b.x-x,b.y-y);if(d<100*power){b.hp-= (100-d)/22*power;b.vx+=(b.x-x)/(d+.1)*8*power;b.vy+=(b.y-y)/(d+.1)*8*power;b.va+=(Math.random-.5)*.18}}for(let i=0;i<28;i++)particles.push({x,y,vx:rand(-7,7),vy:rand(-8,3),life:rand(30,55),c:i%2?'#26333d':'#ff6046'})}
function update(){const dt=1;
for(const b of blocks){if(b.type==='bomb'&&b.hp<=0)explode(b.x,b.y,.7);b.vy+=.38;b.x+=b.vx;b.y+=b.vy;b.a+=b.va;b.vx*=.995;b.vy*=.995;b.va*=.985;if(b.y+b.h/2>world()){b.y=world()-b.h/2;b.vy*=-.18;b.vx*=.82;b.va*=.7;if(Math.abs(b.vy)<.5)b.vy=0}if(b.x-b.w/2<0||b.x+b.w/2>W){b.vx*=-.55;b.x=Math.max(b.w/2,Math.min(W-b.w/2,b.x))}}
for(let i=blocks.length-1;i>=0;i--)if(blocks[i].hp<=0||blocks[i].y>H+100)blocks.splice(i,1);
for(let i=0;i<blocks.length;i++)for(let j=i+1;j<blocks.length;j++){const a=blocks[i],b=blocks[j];const dx=b.x-a.x,dy=b.y-a.y,ox=(a.w+b.w)/2-Math.abs(dx),oy=(a.h+b.h)/2-Math.abs(dy);if(ox>0&&oy>0){if(ox<oy){const s=Math.sign(dx)||1;a.x-=ox/2*s;b.x+=ox/2*s;a.vx-=s*.35;b.vx+=s*.35}else{const s=Math.sign(dy)||1;a.y-=oy/2*s;b.y+=oy/2*s;a.vy-=s*.25;b.vy+=s*.25;a.va+=(dx*.001);b.va-= (dx*.001)}}}
for(const b of birdsList){if(!b.shot){continue}b.vy+=.32;b.x+=b.vx;b.y+=b.vy;b.vx*=.997;b.trail.push({x:b.x,y:b.y});if(b.trail.length>16)b.trail.shift();if(b.y+b.r>world()){b.y=world()-b.r;b.vy*=-.38;b.vx*=.72;if(Math.abs(b.vy)<1)b.vy=0}if(b.x<-30||b.x>W+30||b.y>H+40)b.alive=false;
for(let i=blocks.length-1;i>=0;i--){const p=blocks[i];const closestX=Math.max(p.x-p.w/2,Math.min(b.x,p.x+p.w/2)),closestY=Math.max(p.y-p.h/2,Math.min(b.y,p.y+p.h/2));if(Math.hypot(b.x-closestX,b.y-closestY)<b.r){p.hp-=p.type==='glass'?2:.9;p.vx+=b.vx*.45;p.vy+=b.vy*.35;p.va+=(b.vx*.012);b.vx*=-.35;b.vy*=-.25;shake=4;if(p.type==='bomb')explode(p.x,p.y,1)}}}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.vy+=.25;p.x+=p.vx;p.y+=p.vy;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
if(phase==='aim'&&!drag){const living=birdsList.filter(b=>b.alive);if(!living.length){if(birds>0){spawnBird()}else if(!won){setTimeout(()=>{if(blocks.length<5)finish(true);else finish(false)},600);won=true}}}
if(phase==='aim'&&blocks.length===0&&!won){finish(true);won=true}}
function finish(victory){phase='end';document.getElementById('gameOver').style.display='flex';document.getElementById('resultTitle').textContent=victory?'VICTORY!':'TOWER SURVIVED';document.getElementById('resultScore').textContent=victory?'The rival tower is rubble!':'The tower is still standing';}
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function draw(){ctx.save();if(shake>0){ctx.translate(rand(-shake,shake),rand(-shake,shake));shake*=.85;if(shake<.2)shake=0}drawSky();drawScenery();drawBuildZone();for(const b of blocks)drawBlock(b);drawSlingshot();for(const b of birdsList)drawBird(b);for(const p of particles){ctx.globalAlpha=Math.min(1,p.life/20);ctx.fillStyle=p.c;ctx.fillRect(p.x,p.y,5,5)}ctx.globalAlpha=1;ctx.restore();}
function drawSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#70c8eb');g.addColorStop(.75,'#caecdf');g.addColorStop(1,'#f4c86d');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.fillStyle='rgba(255,245,180,.25)';ctx.beginPath();ctx.arc(W*.78,H*.16,58,0,7);ctx.fill();ctx.fillStyle='#fff';for(const c of clouds){ctx.globalAlpha=.85;ctx.beginPath();ctx.arc(c.x,c.y,18*c.s,0,7);ctx.arc(c.x+22*c.s,c.y-5*c.s,24*c.s,0,7);ctx.arc(c.x+48*c.s,c.y+2*c.s,17*c.s,0,7);ctx.fill()}ctx.globalAlpha=1}
function drawScenery(){ctx.fillStyle='#72b95d';ctx.fillRect(0,world(),W,H-world());ctx.fillStyle='#5b9d4d';for(let x=-20;x<W;x+=55){ctx.beginPath();ctx.moveTo(x,world());ctx.lineTo(x+14,world()-rand(8,18));ctx.lineTo(x+28,world());ctx.fill()}ctx.fillStyle='#d0b577';ctx.fillRect(0,world()+18,W,H-world()-18);ctx.fillStyle='#ebd99e';ctx.fillRect(0,world()+15,W,4)}
function drawBuildZone(){if(phase==='build'){ctx.fillStyle='rgba(255,255,255,.12)';ctx.fillRect(W*.62,74,W*.38,world()-74);ctx.strokeStyle='rgba(38,51,61,.12)';ctx.setLineDash([8,8]);ctx.strokeRect(W*.62,74,W*.38,world()-74);ctx.setLineDash([])}}
function drawBlock(b){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.a);ctx.lineWidth=3;ctx.strokeStyle='#26333d';if(b.type==='wood'){ctx.fillStyle='#b9783f';roundRect(-b.w/2,-b.h/2,b.w,b.h,4);ctx.fill();ctx.stroke();ctx.strokeStyle='#e7ae67';ctx.lineWidth=2;for(let x=-b.w/2+8;x<b.w/2;x+=12){ctx.beginPath();ctx.moveTo(x,-b.h/2+5);ctx.lineTo(x,b.h/2-5);ctx.stroke()}}else if(b.type==='stone'){ctx.fillStyle='#87949b';roundRect(-b.w/2,-b.h/2,b.w,b.h,5);ctx.fill();ctx.stroke();ctx.fillStyle='#aab4b7';ctx.fillRect(-b.w/2+5,-b.h/2+5,10,8)}else if(b.type==='glass'){ctx.fillStyle='rgba(111,218,234,.72)';roundRect(-b.w/2,-b.h/2,b.w,b.h,5);ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(-b.w/2+8,-b.h/2+5);ctx.lineTo(b.w/2-8,b.h/2-5);ctx.stroke()}else{ctx.fillStyle='#26333d';ctx.beginPath();ctx.arc(0,0,b.w/2,0,7);ctx.fill();ctx.strokeStyle='#26333d';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(7,-12);ctx.lineTo(13,-21);ctx.stroke();ctx.fillStyle='#ff6046';ctx.beginPath();ctx.arc(0,2,5,0,7);ctx.fill()}ctx.restore()}
function drawSlingshot(){const s=slingshot();ctx.save();ctx.lineCap='round';ctx.strokeStyle='#5a3928';ctx.lineWidth=13;ctx.beginPath();ctx.moveTo(s.x-18,world()-20);ctx.lineTo(s.x-16,s.y-25);ctx.lineTo(s.x-30,s.y-48);ctx.moveTo(s.x+18,world()-20);ctx.lineTo(s.x+16,s.y-25);ctx.lineTo(s.x+30,s.y-48);ctx.stroke();ctx.restore()}
function drawBird(b){if(!b.alive)return;ctx.save();if(b.shot){ctx.globalAlpha=.35;for(let i=0;i<b.trail.length;i+=3){const t=b.trail[i];ctx.beginPath();ctx.arc(t.x,t.y,Math.max(2,i*.5),0,7);ctx.fillStyle='#26333d';ctx.fill()}ctx.globalAlpha=1}ctx.translate(b.x,b.y);ctx.fillStyle='#26333d';ctx.beginPath();ctx.arc(0,0,b.r+2,0,7);ctx.fill();ctx.fillStyle='#ef5a43';ctx.beginPath();ctx.arc(0,0,b.r-2,0,7);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(5,-5,5,0,7);ctx.fill();ctx.fillStyle='#26333d';ctx.beginPath();ctx.arc(7,-5,2,0,7);ctx.fill();ctx.fillStyle='#ffd84b';ctx.beginPath();ctx.moveTo(b.r-3,-1);ctx.lineTo(b.r+11,4);ctx.lineTo(b.r-3,8);ctx.fill();ctx.restore()}
let last=0;function loop(t){update();draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
})();

